import java.util.*;import java.lang.reflect.*;import com.koios.game.arpg.*;import com.koios.game.model.*;import com.koios.game.model.player.Player;import com.koios.game.map.*;
public final class HubPlacementCheck {
 static int checks;static void check(boolean b,String text){checks++;if(!b)throw new AssertionError(text);}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();for(int sample=0;sample<4;sample++){Player p=PrototypeIntegrationCheck.player("hubclear"+sample,80+sample);p.setAttribute("starter-claimed",true);p.setAttribute("tutorial-stage",11);p.setAttribute("intro-complete",true);MapRuns.home(p);PrototypeIntegrationCheck.idle(p);Location spawn=p.getLocation().copy();Field homes=MapRuns.class.getDeclaredField("HOMES");homes.setAccessible(true);Object base=((Map<?,?>)homes.get(null)).get(p);Field field=base.getClass().getDeclaredField("fixtures");field.setAccessible(true);List<Location> fixtures=(List<Location>)field.get(base);check(fixtures.size()==3&&HubServices.services(p).size()==2,"Three fixtures and two services fit actual private-base terrain");for(HubServices.ServiceMob service:HubServices.services(p)){check(MapRuns.reachable(spawn,8).contains(service.getLocation()),"Service anchor remains walk-reachable");for(Location anchor:fixtures){RSObject object=MapRegion.getObject(anchor.getX(),anchor.getY(),0);ObjectDefinition def=ObjectDefinition.getById(object.getId());for(int x=0;x<def.xLength;x++)for(int y=0;y<def.yLength;y++)check(Math.abs(service.getX()-anchor.getX()-x)+Math.abs(service.getY()-anchor.getY()-y)>=3,"Every service clears every fixture footprint tile by three Manhattan tiles");}}for(Location anchor:fixtures){boolean approach=false;for(Location at:MapRuns.reachable(spawn,8)){if(Location.getManhattanDistance(at,anchor)>2||MapRegion.getObject(at.getX(),at.getY(),0)!=null)continue;boolean occupied=false;for(HubServices.ServiceMob service:HubServices.services(p))if(Location.getManhattanDistance(service.getLocation(),at)<=1)occupied=true;if(!occupied)approach=true;}check(approach,"Each base fixture retains a reachable click approach clear of service NPCs");}System.out.println("Hub service offsets: "+(HubServices.services(p).get(0).getX()-spawn.getX())+","+(HubServices.services(p).get(0).getY()-spawn.getY())+" / "+(HubServices.services(p).get(1).getX()-spawn.getX())+","+(HubServices.services(p).get(1).getY()-spawn.getY()));MapRuns.cleanup(p);}System.out.println("Passed "+checks+" staged hub fixture clearance checks.");}
}
